window.BOOK={"key":"munajat","app":"mutoon-munajat","lsk":"mutoon_munajat_v1","prefix":"mu_","title":"منظومات المناجاة","sub":"في الأنس بالله ومناجاته · ٨ قصائد","poems":[{"id":"suhayli","title":"يا من يرى ما في الضمير ويسمع","nazim":"أبو القاسم عبد الرحمن السهيلي","death":"ت ٥٨١هـ","meter":"الكامل","source":"الشعر العربي (arabic-poetry.net)، وذكرها ابن كثير في البداية والنهاية","srcUrl":"https://arabic-poetry.net/poem/259700","note":"ذكر ابن كثير أن السهيلي كان يقول: ما سأل الله بها أحد حاجة إلا أعطاه إياها. ولا يصح في فضلها حديث مرفوع (إسلام ويب، الفتوى ٤٦٠٠٢).","verses":[["يا من يرى ما في الضمير ويسمع","أنت المعد لكل ما يتوقع"],["يا من يرجى للشدائد كلها","يا من إليه المشتكى والمفزع"],["يا من خزائن رزقه في قول كن","امنن فإن الخير عندك أجمع"],["ما لي سوى فقري إليك وسيلة","فبالافتقار إليك فقري أدفع"],["ما لي سوى قرعي لبابك حيلة","فلئن رددت فأي باب أقرع"],["ومن الذي أدعو وأهتف باسمه","إن كان فضلك عن فقيرك يمنع"],["حاشا لمجدك أن يقنط عاصيا","الفضل أجزل والمواهب أوسع"]],"gharib":[{"w":"المفزع","t":"و (المفزع) بوزن المجمع الملجأ."},{"w":"وسيلة","t":": (الوسيلة) ما يتقرب به إلى الغير والجمع (الوسيل) و (الوسائل) ."},{"w":"أقرع","t":": (قرع) الباب من باب قطع."},{"w":"أهتف","t":"و (هتف) به صاح به، يهتف بالكسر (هتافا) بكسر الهاء."},{"w":"يقنط","t":": (القنوط) اليأس وبابه جلس ودخل وطرب وسلم فهو (قنط) و (قنوط) و (قانط) وقرئ: «فلا تكن من القنطين» فأما (قنط) يقنط بالفتح فيهما و (قنط) يقنط بالكسر فيهما فإنما هو على الجمع بين اللغتين."},{"w":"أجزل","t":"و (الجزيل) العظيم، وعطاء (جزل) و (جزيل) ، و (أجزل) له من العطاء أي أكثر."},{"w":"المواهب","t":"(وهب) له شيئا يهب (وهبا) بوزن وضع يضع وضعا وأيضا بفتح الهاء و (هبة) بكسر الهاء، والاسم (الموهب) و (الموهبة) بكسر الهاء فيهما."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"shafii","title":"ولمّا قسا قلبي وضاقت مذاهبي","nazim":"الإمام محمد بن إدريس الشافعي","death":"ت ٢٠٤هـ","meter":"الطويل","source":"الديوان (aldiwan.net)، من شعره قبل موته","srcUrl":"https://www.aldiwan.net/poem24634.html","note":"تنتشر للقصيدة نسخ أطول فيها أبيات بلا مصدر؛ المعتمد هنا نسخة الديوان (١٢ بيتًا). صُحّح في البيت ٦ «مَن» إلى «مِن»، وفي البيت ٩ «الشُّهد» إلى «السُّهد».","verses":[["وَلَمّا قَسا قَلبي وَضاقَت مَذاهِبي","جَعَلتُ الرَجا مِنّي لِعَفوِكَ سُلَّما"],["تَعاظَمَني ذَنبي فَلَمّا قَرَنتُهُ","بِعَفوِكَ رَبّي كانَ عَفوُكَ أَعظَما"],["فَما زِلتَ ذا عَفوٍ عَنِ الذَنبِ لَم تَزَل","تَجودُ وَتَعفو مِنَّةً وَتَكَرُّما"],["فَلَولاكَ لَم يَصمُد لِإِبليسَ عابِدٌ","فَكَيفَ وَقَد أَغوى صَفِيَّكَ آدَما"],["فَلِلَّهِ دَرُّ العارِفِ النَدبِ إِنَّهُ","تَفيضُ لِفَرطِ الوَجدِ أَجفانُهُ دَما"],["يُقيمُ إِذا ما اللَيلُ مَدَّ ظَلامَهُ","عَلى نَفسِهِ مِن شِدَّةِ الخَوفِ مَأتَما"],["فَصيحاً إِذا ما كانَ في ذِكرِ رَبِّهِ","وَفي ما سِواهُ في الوَرى كانَ أَعجَما"],["وَيَذكُرُ أَيّاماً مَضَت مِن شَبابِهِ","وَما كانَ فيها بِالجَهالَةِ أَجرَما"],["فَصارَ قَرينَ الهَمِّ طولَ نَهارِهِ","أَخا السُهدِ وَالنَجوى إِذا اللَيلُ أَظلَما"],["يَقولُ حَبيبي أَنتَ سُؤلي وَبُغيَتي","كَفى بِكَ لِلراجينَ سُؤلاً وَمَغنَما"],["أَلَستَ الَّذي غَذَّيتَني وَهَدَيتَني","وَلا زِلتَ مَنّاناً عَلَيَّ وَمُنعِما"],["عَسى مَن لَهُ الإِحسانُ يَغفِرُ زَلَّتي","وَيَستُرُ أَوزاري وَما قَد تَقَدَّما"]],"gharib":[{"w":"مذاهبي","t":"و (ذهب) يذهب (ذهابا) و (ذهوبا) و (مذهبا) بفتح الميم أي مر."},{"w":"يصمد","t":": (الصمد) السيد لأنه يصمد إليه في الحوائج أي يقصد."},{"w":"الندب","t":"ورجل (ندب) بوزن ضرب أي خفيف في الحاجة."},{"w":"الوجد","t":"و (وجد) في الحزن (وجدا) بالفتح."},{"w":"مأتما","t":": (المأتم) عند العرب نساء يجتمعن في الخير والشر والجمع (المآتم) وعند العامة المصيبة يقولون: كنا في مأتم فلان، والصواب كنا في مناحة فلان."},{"w":"النجوى","t":"و (انتجاه) خصه (بمناجاته) والاسم (النجوى) ."},{"w":"السهد","t":"(السهاد) الأرق وبابه طرب."},{"w":"أوزاري","t":"والوزر الإثم والثقل والكارة والسلاح."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"munfarija","title":"المنفرجة: اشتدّي أزمةُ تنفرجي","nazim":"أبو الفضل يوسف بن محمد التوزري، المعروف بابن النحوي","death":"ت ٥١٣هـ","meter":"المتدارك (الخبب)","source":"الأضواء البهجة في إبراز دقائق المنفرجة، لزكريا الأنصاري (ت ٩٢٦هـ)","srcUrl":"https://shamela.ws/book/34493","note":"الأشهر نسبتها لابن النحوي، وقيل لغيره. قال تاج الدين السبكي: «وهي مجرّبة لكشف الكروب» (نقله زكريا الأنصاري). صُحّحت أخطاء طباعية ظاهرة: «يضفر» ← «يظفر»، «إلي» ← «إلى»، «أبي عمر» ← «أبي عمرو»، «الستحيي» ← «المستحيي».","verses":[["اشتدي أزمة تنفرجي","قد آذن ليلك بالبلج"],["وظلام الليل له سرج","حتى يغشاه أبو السرج"],["وسحاب الخير لها مطر","فإذا جاء الإبان تجي"],["وفوائد مولانا جمل","بسروح الأنفس والمهج"],["ولها أرج محيى أبدا","فاقصد محيا ذاك الأرج"],["فلربتما فاض المحيا","ببحور الموج من اللجج"],["والخلق جميعا في يده","فذوو سعة وذوو حرج"],["ونزولهم وطلوعهم","فعلى درك وعلى درج"],["ومعائشهم وعواقبهم","ليست في المشي على عوج"],["حكم نسجت بيد حكمت","ثم انتسجت بالمنتسج"],["فإذا اقتصدت ثم انعرجت","فبمقتصد وبمنعرج"],["شهدت بعجائبها حجج","قامت بالأمر على الحجج"],["ورضا بقضاء الله حجى","فعلى مركوزته فعج"],["وإذا انفتحت أبواب هدى","فاعجل لخزائنها ولج"],["وإذا حاولت نهايتها","فاحذر إذ ذاك من العرج"],["لتكون من السباق إذا","ما جئت إلى تلك الفرج"],["فهناك العيش وبهجته","فلمبتهج ولمنتهج"],["فهج الأعمال إذا ركدت","فإذا ما هجت إذا تهج"],["ومعاصي الله سماجتها","تزدان لذي الخلق السمج"],["ولطاعته وصباحتها","أنوار صباح منبلج"],["من يخطب حور الخلد بها","يظفر بالحور وبالغنج"],["فكن المرضي لها بتقى","ترضاه غدا وتكون نجى"],["واتل القرآن بقلب ذي","حزن وبصوت فيه شجي"],["وصلاة الليل مسافتها","فاذهب فيها بالفهم وجي"],["وتأملها ومعانيها","تأت الفردوس وتنفرج"],["واشرب تسنيم مفجرها","لا ممتزجا وبممتزج"],["مدح العقل الآتيه هدى","وهوى متول عنه هجى"],["وكتاب الله رياضته","لعقول الخلق بمندرج"],["وخيار الخلق هداتهم","وسواهم من همج الهمج"],["وإذا كنت المقدام فلا","تجزع في الحرب من الرهج"],["وإذا أبصرت منار هدى","فاظهر فردا فوق الثبج"],["وإذا اشتاقت نفس وجدت","ألما بالشوق المعتلج"],["وثنايا الحسنا ضاحكة","وتمام الضحك على الفلج"],["وعياب الأسرار قد اجتمعت","بأمانتها تحت الشرج"],["والرفق يدوم لصاحبه","والخرق يصير إلى الهرج"],["صلوات الله على المهدي","الهادي الناس إلى النهج"],["وأبي بكر في سيرته","ولسان مقالته اللهج"],["وأبي حفص وكرامته","في قصة سارية الخلج"],["وأبي عمرو ذي النورين","المستحيي المستحيا البهج"],["وأبي حسن في العلم إذا","وافى بسحائبه الخلج"]],"sharh":{"1":"اشتدي أزمة تنفرجي قد آذن ليلك بالبلج اشتدي يا أزمة : أي يا شدة ، وهي ما يصيب الإنسان من الأمور المقلقة من الأمراض وغيرها تنفرجي بالجزم جوابا للأمر ، أي تذهبي ، بمعنى يذهب همك عنا ، وهذه براعة استهلال ، وهي أن يكون المطلع على ما بنيت عليه القصيدة ونحوها ، كأنه بنى قصيدته على سلوك طريق الآخرة ؛ لتصفية القلب ، ورياضة النفس ، ومضمون البيت أن الشدة يعقبها الفرج ، فقد أنبأ عما قصده ؛ لأن سلوك طريق الآخرة فيه على النفس أعظم مشقة يعقبها أتم الفرج . قد آذن بالمد ،وفتح المعجمة : أي أعلم ليلك بالبلج : أي ضياء الصبح ، استعارة للفرج ؛ لاشتراكهما في الإذهاب ، والتحصيل ؛ لأن الضياء يذهب الظلمة ، والفرج يذهب الحزن ، ويحصل بكل منهما السرور ، وعطف على الجملة السابقة قوله :","2":"وظلام الليل له سرج حتي يغشاه أبو السرج وظلام الليل له سرج : وهي الكواكب غير الشمس يمتد نورها حتي 4 يغشاه أبو السرج : وهو الشمس ، وجعلت أباها ؛ لأنها الأصل ، إذ بنورها يذهب نور تلك ؛ ولأن نور القمر الذي هو أقوى من نور بقية الكواكب الليلية مستفاد من نورها ، على ما قاله أهل الهيئة ، والمراد أن الكروب الشديدة لابد في أثنائها من ألطاف يخف معها الألم حتى يتفضل الله بالفرج التام ، الذي لا ألم معه ، ولا كرب ، كالليل المظلم ، جعل الله فيه الكواكب ، يقل بها ظلامه ، ويخف بها قبضه ، حتى يدخل النهار ، فيذهب به ظلامه ، وتنبسط الشمس بضوئه ، وفي البيت الجناس التام ، وهو أن يتفق اللفظان في أنواع الحروف ، وأعدادها ، وهيئاتها ، وترتيبها ،وهو هنا في سرج والسرج ، ورد العجز على الصدر ، وهو إعادة اللفظة بعينها ، وما تصرف منها في آخر المصراع الثاني ، بعد ذكرها في صدره ، وعطف على الجملة السابقة قوله :","3":"وسحاب الخير لها مطر فإذا جاء الإبان تجي وسحاب الخير : وهو الغيم لها ، وفي نسخة له مطر فإذا جاء الإبان : وهو بكسر الهمزة ، وتشديد الباء الموحدة : الوقت ، والمراد وقت السحاب تجي : بالقصر للوقف ، أي السحاب لما يبتلي ذوي الشدائد ، ورجائهم بأنها وإن عظمت ففي أثنائها ألطاف وتمديد إلى الفرج التام ، أشار على الحث على التزام الصبر في أزمنة تلك الشدائد ؛ لأنها لا تنقضي إلا بانقضاء زمانها ، ولا يأتي الفرج إلا في زمانه المقدر له ، كالسحاب الذي يكون عنها الخصب بنزول المطر ، لها وقت مقدر ، لا يتقدم عليه ، ولا يتأخر ، فالعاقل لا يسعه إلا الصبر ، وعطف على الجملة أيضا :","4":"وفوائد مولانا جملل لسروح الأنفس والمهج وفوائد مولانا أي ناصرنا تعالى ، والفوائد ما حصل من الأشياء النافعة في 5 الدين والدنيا ، جمل : أي كثيرة لقوله تعالى : [وإن تعدوا نعمة الله لا تحصوها ] الآية بسروح الأنفس والمهج بالسين والحاء ، من سروح الدابة بالغداة ضد الرواح، أي بالعشي ، أي لسروح الأنفس والأرواح بإذهاب أحزانها ، فكيف ييأس العاقل عند اشتداد الأزمة ، والمهج قال الجوهري : وهي الدم ، وقيل : دم القلب ، والمشهور أن الروح هي النفس .","5":"ولها أرج محيى أبدا ... فاقصد محيا ذاك الأرج ولها ، أي للفوائد أرج من أرج الطيب أرجا إذا فاح وانتشر محيى أي محيي النفوس الزكية وهو إعطاء الحياة ، وهي صفة تقتضي الحس5أ والحركة الإرادية ، أي محيى النفوس الزكية بأنها يحييها الله تعالى به أبدا أي دائما فاقصد محيا من الحياة ، أي فأت زمان أو مكان ذاك الأرج ، والمراد قصد ذاك الأرج الشريف في زمانه ، أو مكانه .","6":"فلربتما فاض المحيا ... ببحور الموج من اللجج فلربتما ، أي وقت ، فاض أي كثر فيه ، المحيا : أي مكان الحياة ببحور الموج وهو المرتفع من الماء من أجل اللجج : وهو معظم الماء ، شبه المحيا في كثرة الأنوار والمعارف .","7":"والخلق جميعا في يده ... فذوو سعة وذوو حرج والخلق : بمعنى المخلوقات حال كونه جميعا أي مجموعا في يده : أي قوته أونعمته ، فذوو سعة أي يسار وذوو حرج ، أي ضيق .","8":"ونزولهم وطلوعهم ... فعلى درك وعلى درج أي الخلق من علو إلى سفل حسا أو عقلا ، أعني مرتبة ، وطلوعهم من سفل إلى علو كذلك فعلى درك في الأول ، وعلى درج في الثاني ، يقال : النار دركات ، والجنة درجات .","9":"ومعائشهم وعواقبهم ... ليست في المشي على عوج ومعائشهم في الدنيا من مطاعم وملابس ، وعواقبهم في الآخرة من سعادة وشقاوة ، ليست في المشي إليهم على عوج ، بل مستقيمة ، فإنها مقدرة من الله تعالى ، يتوجه إليهم 6 في أوقاتها ، وإثبات المشي لها استعارة ، يعني شيئا فشيئا .","10":"حكم نسجت بيد حكمت ثم انتسجت بالمنتسج حكم من الله تعالى ، والحكمة صواب الأمر ، يخلق ما يشاء ، نسجت تلك الحكم بيد : أي بقوة الله حكمت : أي قضت في كل الأمور ، ولا راد لما قضى ثم انتسجت ، تلك الحكم ، أي التحمت بالمنتسج : أي المؤتلف ، والمراد به العبد المقضي عليه بالمقادير .","11":"فإذا اقتصدت ثم انعرجت ... فبمقتصد وبمنعرج فإذا اقتصدت : أي توسطت في نظر العقل ، ثم انعرجت : أي مالت فيه ، فبمقتصد : أي فاقتصادها وانعراجها كائنان بمقتصد ، وبمنعرج : وهو العبد المقضي عليه ، فيصير باقتصادها في نظره مقتصدا ، وبانعراجها فيه منفرجا ، كما يصير باكتمالها فيه مكتملا .","12":"شهدت بعجائبها حجج قامت بالأمر على الحجج ... شهدت بعجائبها : أي الحكم ، وأنواع المخلوقات ، حجج : أي أدلة ، كما شهدت بكمال وجود صانعها ، قامت : أي استقلت ، أو دامت ، وظهرت ، بالأمر : أي الشأن ، أو الوصف ، أي قامت بشأن الربوبية ، أو بوصفها بوصفها على ممن الحجج : أي السنين .","13":"ورضا بقضاء الله حجى ... فعلى مركوزته فعج ... ورضا بقضاء الله تعالى حجى : أي عقل ، فحقيق على كل مؤمن يصون به إيمانه ، وسائر طاعاته ، فعلى مركوزته : أي لا غيرها ، فعج : أي فاعطف ، يقال عجيت البعير إذا عطفت رأسه بزمامه ، أي لكون الرضا حقيقا على كل مؤمن .","14":"وإذا انفتحت أبواب هد فاعجل لخزائنها ولج ... وإذا انفتحت لك أبواب هدى : أي اهتداء بأن خلقه الله فيك ، فاعجل : أي 7 فاسرع لخزائنها : جمع خزانة بكسر الخاء ، ولج : أي ادخل ، فيها في تلك المقامات والمعارف بخزائن لها أبواب مغلقة ، بجامع أن المشبه مظنة للقرب من الله ، الذي هو أعظم مطلوب .","15":"وإذا حاولت نهايتها فاحذر إذ ذاك من العرج وإذا حاولت : أي طلبت نهايتها : أي الأبواب ، أو الهدى ، والمعنى إذا طلبت الانتقال إلى مقام أو حال فاحذر إذ ذاك من العرج : أي فالزم فيه حسن الأدب من الثبات عليه ، وموافقة مراد الله تعالى .","16":"لتكون من السباق إذا ... ما جئت إلى تلك الفرج لتكون من السباق إلى فرج الجنة إذا ما زائدة للتأكيد جئت معهم إلى تلك الفرج : أراد بالمجيء السير ، لا بنقل الأقدام ، بل بنظر القلب في المعقولات الموصلة إلى المطلوب ، فإن وصلت إلى تلك الفرج .","17":"فهناك العيش وبهجته ... فلمبتهج ولمنتهج فهناك : أي لا في غيره العيش وبهجته : أي الحياة الكاملة ، وحسنها ، فلمبتهج : أي مسرور بما حصل له من لذة التجلي ، ولمنتهج : وهو الطريق ، استعير للتقوى ، والمراد انتقاله فعلا وحالا في معاني التقوى .","18":"فهج الأعمال إذا ركدت ... فإذا ما هجت إذا تهج فهج الأعمال ، يقال : هاج فلان الشيء إذا أثاره ، وحركه ، أي الأعمال ، وحركها بمعنى أدمها إذا ركدت : أي سكنت لقوله صلى الله عليه وسلم : أحب الأعمال إلى الله أدومه وإن قل ، رواه الشيخان فإذا ما زائدة للتأكيد هجت : أي أدمت الأعمال إذا أي حين إذ قلت تهج أي تدم ، وفيه رد العجز على الصدر .","19":"ومعاصي الله سماجتها ... تزدان لذي الخلق السمج ومعاصي الله تعالى سماجتها أي قبحها تزدان : أي تتزين وتحسن لذي الخلق : ما طبع عليه/ الإنسان بلا تكلف ، كالكرم والشجاعة السمج : أي القبيح . 8","20":"ولطاعته وصباحتها ... أنوار صباح منبلج ولطاعته : أي طاعة الله تعالى وصباحتها : أي جمالها أنوار صباح منبلج :أي أضواء ظاهرة ظهور ضوء الصباح الواضح ، وبها تذهب ظلمات الجهل عن القلب ، وظلمات القبر عن الروح .","21":"من يخطب حور الخلد بها ... يضفر بالحور وبالغنج من يخطب من الشرطية ، وهي طلب التزوج ، أي من يطلب من الله تعالى حور الخلد : أي نساء الجنة ، بها : أي بالطاعة ، ويؤدها يظفر أي يفز ، بالحور الكاملات الحسن ، وسميت نساء الجنة بالحور ؛ لأنهن يشبهن بالضياء ، وهو شدة بياض العين ، في شدة سوادها وبالغنج هو حسن الشكل ، وإذا أردت الظفر بالحور","22":"فكن المرضي لها بتقى ... ترضاه غدا وتكون نجى فكن المرضي لها بتقى : بمعنى التقوى ، أي بسبب تقى منك ترضاه بأن تراه مقبولا أي ثابتا عليه ؛ لموافقة الشرع غدا : أي يوم القيامة ، وأصله غدو ، وتكون به هناك نجى : أي نجيا من المكروهات ، وجعل السبب فيما ذكر التقوى ؛ لأنها أعظم الخصال ، ولهذا وصى الله تعالى بها الأولين والآخرين ، فقال تعالى : [ولقد وصينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله ] .","23":"واتل القرآن بقلب ذي ... حزن وبصوت فيه شجي واتل القرآن متدبرا له بقلب : أي فؤاد ذي حزن أي حزين ، محترق ومحسنا وبصوت فيه شجي : أي حزين ، بمعنى رقيق ، من قولهم : فلان يقرأ بالتحزين إذا رقق صوته ، وذلك لقوله تعالى : [ورتل القرآن ترتيلا ] ، ولخبر الترمذي : يقول الله تعالى من شغله القرآن عن ذكري ومسألتي أعطيته أفضل ما أعطي السائلين ، وفضل كلام9 الله على سائر الكلام كفضل الله على جميع خلقه .","24":"وصلاة الليل مسافتها ... فاذهب فيها بالفهم وجي وصلاة وفي نسخة قيام الليل : أي نافلتة ، وهي أفضل من نافلة النهار مسافتها : أي مسافة التلاوة وفيها فاذهب فيها بالفهم : أي بالعلم وجي ، قال الله تعالى : [ من أهل الكتاب أمة قائمة يتلون آيات الله آناء الليل وهم يسجدون ] الآية ، روى الطبراني: شرف المؤمن قيام الليل ، وصلاة الليل محل لكثرة التلاوة ، فاخصص التلاوة فيها بمزيد حضور .","25":"وتأملها ومعانيها ... تأت الفردوس وتنفرج وتأملها : أي صلاة الليل ، وتأمل معانيها : أي مقاصدها الدينية والدنيوية الواردة في الأخبار ، كخبر : عليكم بقيام الليل فإنه دأب الصالحين من قبلكم ، ومقربكم إلى ربكم ، ومكفرة للسيئات ، ومطردة للداء عن الجسد ، ومنهاة عن الإثم . رواه الترمذي وغيره . تأت الفردوس : وهو حديقة أعلى الجنة وأوسطها ، لخبر البخاري : فإذا سألتم الله تعالى فاسألوه الفردوس ، فإنه أوسط الجنة ، وأعلى الجنة ، وفوقه عرش الرحمن ، ومنه تفجر أنهار الجنة ، وتنفرج : من الهم والغم .","26":"واشرب تسنيم مفجرها ... لا ممتزجا وبممتزج واشرب بطاعتك تسنيم مفجرها : أي مفجر الفردوس ، وهو الماء المجرى ، من فجرت الماء أي أجريته ، والتسنيم : عين في الجنة ، يشرب منها المقربون ، سميت به لأن شرابها أرفع شراب في الجنة ، وأنها تأتيهم من فوق ، على ما روي أنها تجري في الهواء متسنمة ، فتصب في أوانيهم ، فيشربون منها ما يريدون حالة كونه لا ممتزجا : أي مختلطا بغيره ، وهذا للمقربين ، وبممتزج بغيره وهو للأبرار ، قال تعالى : 10 [ يسقون ] أي الأبرار [ من رحيق ] أي خمر خالصة من الدنس ، ثم قال [ ومزاجه ] أي ما يمزج به [ من تسنيم]","27":"مدح العقل الآتيه هدى ... وهوى متول عنه هجى مدح العقل الآتيه : أي الذي أتى بأمر من الطاعة وغيرها من المقامات ، وأجلها معرفة الله تعالى التي بها سعادة الدارين ، والتي لمناجاته ، وفهم خطابه ، هدى : أي دلالة على الطريق ، والعقل جوهر لطيف في البدن ، ينبعث شعاعه فيه كالسراج في البيت ، ومحله الدماغ ، وهوى : أي ميل النفس إلى الشهوة حلالا أو حراما متول : أي معرض عنه : أي عن ما مر من الطاعة وغيرها من المقامات ، أو عن الهدى ، هجى : ، أي ذم من هجوته ، كما قابل المدح بالذم .","28":"وكتاب الله رياضته ... لعقول الخلق بمندرج وكتاب الله تعالى رياضته : أي تعليمه ، وتأديبه بأمره ، ونهيه ، ووعده ، ووعظه ، وضرب أمثاله لعقول الخلق كائنة بمندرج : أي بطريق واضحة ، يندرج الناس فيها لصحتها ووضوحها ، من درج القوم ، واندرجوا : أي مضوا في سبيلهم .","29":"وخيار الخلق هداتهم ... وسواهم من همج الهمج وخيار الخلق: أي أفضلهم هداتهم إلى طريق الحق ، هم العلماء العاملون ، يقال هديته الطريق ، وإلى الطريق أي دللته عليه ، ويدل لما قاله أدلة كثيرة ، كقوله تعالى : [ شهد الله أنه لا إله إلا هو والملائكة وأولو العلم ] فبدأ بنفسه ، وثنى بالملائكة ، وثلث بأولي العلم دون غيرهم ، وناهيك به شرفا ، وسواهم من همج الهمج لخبر : الناس رجلان عالم ومتعلم ، وسائر الناس همج لا خير فيهم . والهمج/ جمع همجة ، وهي الشاة 11 المهزولة والذباب الصغير الذي يسقط على وجوه الغنم والحمير ، شبه بذلك غير الهداة في قلة الهمة ، وخسة القدر.","30":"وإذا كنت المقدام فلا ... تجزع في الحرب من الرهج وإذا كنت المقدام : أي الكثير الإقدام على العدو بشجاعتك ، وللام فيه للعهد العلمي ، على سبيل الإدعاء للكامل في الإقدام ، أي الجامع لخصائص المقدام ، فلا تجزع : أي تضطرب ، وفي نسخة فلا تلوي ، أي تعرض في الحرب : أي القتال من أجل ، الرهج : أي الغبار ، أي كن في جدك ونشاطك قوي القلب بالله ، نافذ العزم فيما تطلب كالمقدام الذي لا يرده عن مقصده راد وإن عظم ، وإذ كنت كذلك فلا تجزع في مجاهدتك الشيطان والنفس ؛ لأنهما يقولان لك : إن كنت خلقت سعيدا لم يضرك ترك العمل ، أو شقيا لم ينفعك العمل ، فادفع هذه الشبهة بأن تقول أنا عبد الله ، وعلى العبد الامتثال لعبوديته ، والرب يحكم ما يشاء ويفعل ما يريد .","31":"وإذا أبصرت منار هدى ... فاظهر فردا فوق الثبج وإذا أبصرت ، بعد جدك في العلم والعمل ، منار هدى : أي الطريق المستقيم فاظهر فردا : أي فاعل منفردا فوق الثبج : أي الوسط ، أو لمعظم من منار الهدى ؛ لتصير من المختصين به ، والمنار أو ما يحل فيه النور ، وهو أيضا العلم الذي ينصب في الطريق للاهتداء به ، وشبه الهدى بالنوروالمنار الدليل الواضح المفيد للعلم والعمل ، وللشيخ المفيد لذلك ، فقد قالوا : من لم يكن له شيخ فالشيطان شيخه ، وقال الشيخ أبو مدين : من لم يأخذ أدبه من المتأدبين ، أفسد من يتبعه .","32":"وإذا اشتاقت نفس وجدت ... ألما بالشوق المعتلج وإذا اشتاقت نفس : أي مالت إلى محبوبها ميلا تحرق به الأحشاء ، بحيث لا تسكن باللقاء ، بالشوق : أي بسبب شوقها ، المعتلج : أي الشديد ، والاشتياق أعلى من 12 الشوق لأنه لا يسكن باللقاء .","33":"وثنايا الحسنا ضاحكة ... وتمام الضحك على الفلج وثنايا : المرأة ، الحسنا بالفتح ، وهي أربع ثنتان من أعلى ، وثنتان من أسفل ، ضاحكة صاحبتها ، وتمام الضحك : منها على الفلج من فلح بكسرها ، وهو تباعد منابت الأسنان وهو حسن فيهما ، فشبه دلائل العلم ، وأسباب العمل بثنايا امرأة حسناء ، أو كنى بكل من الثنايا والفلح عن المرأة من الحور العين ، وبالضحك عن الرضا والسرور ، أي الحور راضية مسرورة بزوجها المجد في العلم والعمل .","34":"وعياب الأسرار قد اجتمعت ... بأمانتها تحت الشرج ... وعياب : جمع عيبة ، وهي وعاء من جلد تصان فيه الأمتعة ، الأسرار : وهو ما يكتم ، قد اجتمعت : أي عياب الأسرار بأمانتها : أي عليها ، أو معها ، والأمانة ضد الخيانة ، والمراد ما يؤتمن عليه تحت الشرج : بفتح الشين والراء ، أي عرى العياب ، وهو ما يشبه الوعاء ولمراد بالأسرار أسرار الله تعالى في خلقه ، مما حجبهم عنه ، ولم يطلع عليه أحدا إلا من شاء ممن اصطفاه ،قال بعض العارفين : العلم بمنزلة البحر أجري منه واد ، ثم من الوادي نهر ، ثم من النهر جدول ، ثم من الجدول ساقية ، فلو جرى البحر إلى النهر ، والوادي ألى الجدول لغرقه وأفسده ، وهو المراد بقوله : [ أنزل من السماء ماء فسالت أودية بقدرها ] فبحور العلم عند الله ، أعطى الرسل منها أودية ، ثم أعطت الرسل من أوديتها العلماء أنهارا ، ثم أعطت العلماء من أنهارها العامة جداول بقدر طاقتهم ، والمناسب أن يقيد العامة بالمتفقهة ، ويقال ثم أعطت المتفقهة من جدولها غيرهم سواقي ، وسبب 13 ذلك أن العقول الضعيفة لا تحمل الأسرار القوية ، كما لا يبصر الخفاش نور الشمس ، ومما أخفاه الله عن خلقه رضاه عنهم .","35":"والرفق يدوم لصاحبه ... والخرق يصير إلى الهرج والرفق ... : وهو التوسط واللطافة في الأمر والفعل ، من الأول : رفق بالفتح ، ومن الثاني بالفتح والضم يدوم به العمل لصاحبه والخرق : ضد الرفق ، يصير إلى الهرج بإسكان الراء الفتنة ، وكثرة الفساد ، وبفتحها تحير البصر ، روى ابن حبان في صحيحه : ما كان الرفق في شيء قط إلا زانه ، وما كان الخرق ، وفي رواية الفحش في شيء قط إلا شانه ، وإن الله رفيق يحب الرفق ، رواه البخاري . ... ولما فرغ من التنبية على التصفية القلبية ، والتزكية النفسية وعلى المقامات العلمية ، ختم ذلك بالدعاء للنبي صلى الله عليه وسلم ، الواضع لتلك المسائك ، ولإصحابه الأربعة ، الخلفاء الحافظين طريقه ، الكاشفين لما أشكل من ذلك رضي الله عنهم ، وعن سائر الصحابة .","36":"صلوات الله على المهدي ... الهادي الناس إلي النهج صلوات الله تعالى : وهي من الله تعالى رحمة ، ومن الملائكة الاستغفار ، ومن الآدمي تضرع ودعاء بخير على النبي محمد بن عبد الله المهدي بفتح الميم ، أي الرشيد الموفق بخلق الهداية فيه ؛ لوجود عصمته ، الهادي : أي المرشد الناس من الإنس والجن ، إلي النهج بفتح الهاء لغة في إسكانها : أي الطريق المستقيم ، قال تعالى : [وإنك لتهدي إلى صراط مستقيم ]","37":"وأبي بكر في سيرته ... ولسان مقالته اللهج وعلى الأمام أبي بكر ، وهو أفضل الصحابة واسمه عبد الله بن أبي قحافة يلتقي 14 مع النبي صلى الله عليه وسلم في مرة ، القرشي ويقال له : عتيق ؛ لعتاقة وجهه ، أي جماله ، وقيل : لأنه صلى الله عليه وسلم قال فيه : من سره أن ينظر إلى عتيق من النار فلينظر إلى أبي بكر ، وصديق لمبادرته إلى تصديق النبي صلى الله عليه وسلم في جميع ما جاء به ، في سيرته : أي طريقته التي منها مبادرته للإسلام وفي لسان مقالته اللهج بكسر الهاء : أي المثابر على الصدق ، فاللهج صفة لسان ، وبالغ فيما قاله ، فجعل لسانه ظرفا للصدق ، فلا يتحرك إلا به .","38":"وأبي حفص وكرامته ... في قصة سارية الخلج وعلى الإمام أبي حفص : عمر بن الخطاب ، يلتقي مع النبي صلى الله عليه وسلم في كعب ، القرشي وكرامته : أي المعروفة الظاهرة ، في قصة سارية أبي حفص حصن ، أو زنيم الديلمي من أنه كان يوم الجمعة يخطب بالمدينة ، فرأى العسكر فجعل يصيح : يا سارية الجبل ، الجبل فصعد سارية وجنده الجبل ، وقاتلوا الكفار ، وهزموهم ، فكتبوا بذلك إلى عمر ، وجاءه البشير بعد شهر ، وأضاف سارية إلى الخلج بفتح اللام : وهو أن يشتكي الرجل عظامه من عمل ، أو طول مشي .","39":"وأبي عمر وذي النورين ... الستحيي المستحيا البهج وعلى الإمام أبي عمرو ، يقال له أبو عبد الله ، وأبو ليلى ، عثمان بن ، يلتقي مع النبي صلى الله عليه وسلم في عبد مناف القرشي ، ذي النورين ؛ لأنه تزوج بنتي النبي صلى الله عليه وسلم ، رقية ، ثن أم كلثوم ، الستحيي المستحيا بكسر ياء أحدهما ، وفتح ياء الآخر ؛ لأن النبي صلى الله عليه وسلم كان جالسا وهو مكشوف الفخذ ، فدخل /عليه 15 أبو بكر فلم يغط فخذه ، ودخل عمر ، فلم يغط فخذه ، ودخل عثمان فغطاه ، وقال : ألا أستحيي ممن استحيت منه ملائكة الرحمن ، واه البخاري ، وروي أنه صلى الله عليه وسلم قال : عثمان أحيى أمتي ، وأكرمها ، وفي نسخة المحي إشارة إلى أنه شهيد ، فهو حي بنص القرآن البهج بالباء : أي حسن الخلق ، قال ابن عبد البر : كان جميلا طويل اللحية ، حسن الوجه .","40":"وأبي حسن في العلم إذا وافى بسحائبه الخلج وعلى الإمام أبي حسن علي بن أبي طالب ، واسمه عبد مناف بن عبد المطلب ، في العلم إذا وافى بسحائبه : جمع سحابة ، وهي الغيم ، الخلج : بضم الخاء واللام : السحاب المتفرق ، ويقال : للسحابة المنفردة الكثيرة الماء ، استعار لأنواع علومه ، أي يفزع إليه في مشكلات العلم ؛ لتعليمه إياهم إذا أتى بعلومه الكثيرة النفع للناس ، وقام الإجماع على غزارة علمه ، وما احتج به من خبر : أنا دار الحكمة ، وفي رواية : مدينة العلم وعلي بابها ، قال الترمذي : إنه منكر ، والنووي : إنه باطل ، ... ومن كلماته : العز تسع كلمات : ثلاث في المناجاة ، وهي : كفاني فخرا أن تكون لي ربا ، وكفاني عزا أن أكون لك عبدا ، وأنت كما أحب فاجعلني كما تحب ، وثلاث في الحكمة ، وهي : قيمة كل امرئ ما يحسنه ، وما هلك امرؤ عرف قدر نفسه ، والمرء مخبوء تحت لسانه ، وثلاث في الأدب ، وهي : استغن عمن شئت فأنت نظيره ، وتفضل على من شئت فأنت أميره ، واضرع لمن شئت فأنت أسيره . ... فهذه من مفاريد كلماته ، وفضائل الأئمة الأربعة كثيرة مذكورة في محالها ، وبعد ... ... وصحابته وقرابته ... ... ... وقفاة الأثر بلا عوج وصحابته : وهم كل مؤمن اجتمع بالنبي صلى الله عليه وسلم ، ومات مسلما ، وقرابته : وهم مؤمنو بني هاشم ، وبني المطلب ، وقفاة الأثر بلا عوج : وهم كل مؤمن اقتفى أثر رسول الله صلى الله عليه وسلم ."},"sharhSrc":{"name":"الأضواء البهجة في إبراز دقائق المنفرجة، لزكريا الأنصاري (ت ٩٢٦هـ)","url":"https://shamela.ws/book/34493"}},{"id":"atahiya","title":"إلهي لا تعذّبني فإنّي","nazim":"أبو العتاهية إسماعيل بن القاسم","death":"ت ٢١١هـ","meter":"الوافر","source":"الديوان (aldiwan.net)","srcUrl":"https://www.aldiwan.net/poem63136.html","verses":[["إِلَهي لا تُعَذِّبني فَإِنّي","مُقِرٌّ بِالَّذي قَد كانَ مِنّي"],["وَما لي حيلَةٌ إِلّا رَجائي","وَعَفوُكَ إِن عَفَوتَ وَحُسنُ ظَنّي"],["فَكَم مِن زِلَّةٍ لي في البَرايا","وَأَنتَ عَلَيَّ ذو فَضلٍ وَمَنِّ"],["إِذا فَكَّرتُ في نَدَمي عَلَيها","عَضَضتُ أَنامِلي وَقَرَعتُ سِنّي"],["يَظُنُّ الناسُ بي خَيراً وَإِنّي","لَشَرُّ الناسِ إِن لَم تَعفُ عَنّي"],["أُجَنُّ بِزَهرَةِ الدُنيا جُنوناً","وَأُفني العُمرَ فيها بِالتَمَنّي"],["وَبَينَ يَدَيَّ مُحتَبَسٌ طَويلٌ","كَأَنّي قَد دُعيتُ لَهُ كَأَنّي"],["وَلَو أَنّي صَدَقتُ الزُهدَ فيها","قَلَبتُ لِأَهلِها ظَهرَ المِجَنِّ"]],"gharib":[{"w":"البرايا","t":": (البرى) التراب و (البرية) الخلق، وأصله الهمزة والجمع (البرايا) و (البريات) وقد (براه) الله أي خلقه وبابه عدا."},{"w":"أناملي","t":"و (الأنملة) بالفتح واحدة (الأنامل) وهي رءوس الأصابع."},{"w":"زهرة الدنيا","t":"(زهرة) الدنيا بالسكون غضارتها وحسنها."},{"w":"المجن","t":"و (المجن) بالكسر الترس وجمعه (مجان) بالفتح."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"abunuwas","title":"يا ربِّ إن عظُمت ذنوبي كثرةً","nazim":"أبو نواس الحسن بن هانئ","death":"ت ١٩٨هـ","meter":"الكامل","source":"الديوان (aldiwan.net)","srcUrl":"https://www.aldiwan.net/poem27209.html","note":"يُروى أنه قالها في آخر حياته.","verses":[["يا رَبِّ إِن عَظُمَت ذُنوبي كَثرَةً","فَلَقَد عَلِمتُ بِأَنَّ عَفوَكَ أَعظَمُ"],["إِن كانَ لا يَرجوكَ إِلّا مُحسِنٌ","فَبِمَن يَلوذُ وَيَستَجيرُ المُجرِمُ"],["أَدعوكَ رَبِّ كَما أَمَرتَ تَضَرُّعاً","فَإِذا رَدَدتَ يَدي فَمَن ذا يَرحَمُ"],["ما لي إِلَيكَ وَسيلَةٌ إِلّا الرَجا","وَجَميلُ عَفوِكَ ثُمَّ أَنّي مُسلِمُ"]],"gharib":[{"w":"يلوذ","t":": (لاذ) به لجأ إليه وعاذ به وبابه قال."},{"w":"يستجير","t":"وامرأة الرجل (جارته) و (استجاره) من فلان (فأجاره) منه."},{"w":"تضرعا","t":"و (تضرع) إلى الله أي ابتهل."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"mubarak","title":"إذا ما الليلُ أظلم كابدوه","nazim":"عبد الله بن المبارك","death":"ت ١٨١هـ","meter":"الوافر","source":"الديوان (aldiwan.net)، وذكر البيتين الأولين ابن رجب في «التخويف من النار»","srcUrl":"https://shamela.ws/book/4033/26","verses":[["إذا ما الليل أظلم كابدوه","فيسفر عنهم وهم ركوع"],["أطار الخوف نومهم فقاموا","وأهل الأمن في الدنيا هجوع"],["لهم تحت الظلام وهم سجود","أنين منه تنفرج الضلوع"],["وخرس بالنهار لطول صمت","عليهم من سكينتهم خشوع"]],"gharib":[{"w":"كابدوه","t":"و (كابد) الأمر قاسى شدته."},{"w":"هجوع","t":": (الهجوع) النوم ليلا وبابه خضع و (التهجاع) النومة الخفيفة."},{"w":"أنين","t":": (أن) الرجل من الوجع يئن بالكسر (أنينا) و (أنانا) أيضا بالضم و (تأنانا) و (إن) و (أن) حرفان ينصبان الاسم ويرفعان الخبر."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"sajjad","title":"يا من يجيب دعا المضطرّ في الظُّلَم","nazim":"منسوبة إلى علي بن الحسين زين العابدين","death":"ت ٩٤هـ","meter":"البسيط","source":"الديوان (aldiwan.net)","srcUrl":"https://www.aldiwan.net/poem76293.html","note":"نسبتها إليه غير ثابتة. وفي بعض النسخ بيت فيه «بحقّ البيت والحرم» لم يُثبت هنا.","verses":[["يا من يجيب دعا المضطرّ في الظلم","يا كاشف الضرّ والبلوى مع السقم"],["قد نام وفدُك حول البيت وانتبهوا","وأنتَ يا حيّ يا قيّومُ لم تنَمِ"],["إن كان جودكَ لا يرجوهُ ذو سفهٍ","فمن يجود على العاصين بالكرمِ"]],"gharib":[{"w":"البلوى","t":": (البلية) و (البلوى) و (البلاء) واحد والجمع (البلايا) ."},{"w":"السقم","t":": (السقام) المرض وكذا (السقم) و (السقم) مثل الحزن والحزن."},{"w":"وفدك","t":": (وفد) فلان على الأمير أي ورد رسولا وبابه وعد فهو (وافد) والجمع (وفد) مثل صاحب وصحب وجمع (الوفد أوفاد) و (وفود) ، والاسم (الوفادة) بالكسر."},{"w":"القيوم","t":"و (القيوم) اسم من أسماء الله تعالى."},{"w":"سفه","t":": (السفه) ضد الحلم وأصله الخفة والحركة."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}},{"id":"mimiyya","title":"من ميمية ابن القيم: الشوق إلى الجنة ورؤية الله","nazim":"شمس الدين ابن قيم الجوزية","death":"ت ٧٥١هـ","meter":"الطويل","source":"مقدمة «حادي الأرواح إلى بلاد الأفراح»","srcUrl":"https://shamela.ws/book/11147","note":"مقطعان مختاران: الأبيات التسعة الأولى، ثم من «فحيّ على جنات عدن» إلى «فإن كنت لا تدري فتلك مصيبة». تُرك ما بينهما من وصف الحور. صُحّح «ذاهم» إلى «إذا هم».","verses":[["وما ذاك إلا غيرة أن ينالها","سوى كفئها والرب بالخلق أعلم"],["وإن حجبت عنا بكل كريهة","وحفت بما يؤذي النفوس ويؤلم"],["فلله ما في حشوها من مسرة","وأصناف لذات بها يتنعم"],["ولله برد العيش بين خيامها","وروضاتها والثغر في الروض يبسم"],["ولله واديها الذي هو موعد الـ","ـمزيد لوفد الحب لو كنت منهم"],["بذيالك الوادي يهيم صبابة","محب يري أن الصبابة مغنم"],["ولله أفراح المحبين عندما","يخاطبهم من فوقهم ويسلم"],["ولله أبصار ترى الله جهرة","فلا الضيم يغشاها ولا هي تسأم"],["فيا نظرة أهدت إلى الوجه نضرة","أمن بعدها يسلو المحب المتيم"],["فحي على جنات عدن فأنها","منازلها الأولى وفيها المخيم"],["ولكننا سبي العدو فهل ترى","نعود إلى أوطاننا ونسلم"],["وقد زعموا أن الغريب إذا نأى","وشطت به أوطانه فهو مغرم"],["وأي اغتراب فوق غربتنا التي","لها أضحت الأعداء فينا تحكم"],["وحي على السوق الذي فيه يلتقي","المحبون ذاك السوق للقوم تعلم"],["فما شئت خذ منه بلا ثمن له","فقد أسلف التجار فيه واسلموا"],["وحي على يوم المزيد الذي به","زيارة رب العرش فاليوم موسم"],["وحي على واد هنالك أفيح","وتربته من إذفر المسك أعظم"],["منابر من نور هناك وفضة","ومن خالص العقيان لا تتقصم"],["وكثبان مسك قد جعلن مقاعدا","لمن دون أصحاب المنابر يعلم"],["فبينا هموا في عيشهم وسرورهم","وأرزاقهم تجري عليهم ونقسم"],["إذا هم بنور ساطع أشرقت له","بأقطارها الجنات لا يتوهم"],["تجلى لهم رب السماوات جهرة","فيضحك فوق العرش ثم يكلم"],["سلام عليكم يسمعون جميعهم","بآذانهم تسليمه إذ يسلم"],["يقول سلوني ما أشتهيتم فكل ما","تريدون عندي أنني أنا أرحم"],["فقالوا جميعا نحن نسألك الرضا","فأنت الذي تولى الجميل وترحم"],["فيعطيهم هذا ويشهد جميعهم","عليه تعالى الله فالله أكرم"],["فيا بائعا هذا ببخس معجل","كأنك لا تدري بلى سوف تعلم"],["فإن كنت لا تدري فتلك مصيبة","وإن كنت تدري فالمصيبة أعظم"]],"gharib":[{"w":"كفئها","t":": (الكفيء) بالمد النظير وكذا (الكفء) و (الكفؤ) بسكون الفاء وضمها بوزن فعل وفعل."},{"w":"حفت","t":"و (حفوا) حوله أي أطافوا به واستداروا."},{"w":"صبابة","t":"و (الصبابة) بالفتح رقة الشوق وحرارته."},{"w":"الضيم","t":": (الضيم) الظلم وقد (ضامه) من باب باع فهو (مضيم) و (استضامه) فهو (مستضام) أي مظلوم."},{"w":"يسلو","t":": (سلا) عنه من باب سما و (سلي) عنه بالكسر (سليا) مثله."},{"w":"المخيم","t":"و (خيم) أيضا بالمكان أقام به و (تخيم) بمكان كذا ضرب خيمته به."},{"w":"شطت","t":": (شطت) الدار تشط بضم الشين وكسرها (شطا) و (شطوطا) بعدت."},{"w":"إذفر","t":": (الذفر) بفتحتين كل ريح ذكية من طيب أو نتن يقال: مسك (أذفر) بين الذفر وبابه طرب."},{"w":"العقيان","t":": (العقيان) الذهب الخالص."}],"gsrc":{"name":"مختار الصحاح، لزين الدين الرازي (ت ٦٦٦هـ)","url":"https://shamela.ws/book/23193"}}]};
